 "content": "def transform(grid):
    """Repeat the observed diagonal-color sequence across the whole grid."""
    n, m = len(grid), len(grid[0])
    diagonal_colors = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                d = c - r
                if d in diagonal_colors and diagonal_colors[d] != color:
                    raise ValueError("Input diagonal is not uniformly colored")
                diagonal_colors[d] = color

    # The diagonal motif period is the smallest modulus that makes all
    # observed diagonals consistent. Color each residue class accordingly.
    period = 1
    for candidate in range(1, n + m + 1):
        residues = {}
        consistent = True
        for d, color in diagonal_colors.items():
            residue = d % candidate
            if residue in residues and residues[residue] != color:
                consistent = False
                break
            residues[residue] = color
        if consistent:
            period = candidate
            break

    residues = {d % period: color for d, color in diagonal_colors.items()}
    # Every residue should be represented by the input motif. For a missing
    # residue, cycle forward through the known diagonal sequence.
    ordered = sorted(diagonal_colors)
    for residue in range(period):
        if residue not in residues:
            nearest = min(ordered, key=lambda d: ((d % period - residue) % period))
            residues[residue] = diagonal_colors[nearest]

    return [[residues[(c - r) % period] for c in range(m)] for r in range(n)]


